<?php
declare(strict_types=1);
final class PdfService {
    public static function generateFinal(int $documentId): array {RbacService::authorize('documents.sign');$d=DocumentService::find($documentId);if(!in_array($d['status'],['approved','signed'],true))throw new RuntimeException('Dokumen belum disetujui.',409);require_once dirname(__DIR__,2).'/tcpdf/tcpdf.php';$code=$d['verification_code']?:strtoupper(bin2hex(random_bytes(8)));$verifyUrl=(isset($_SERVER['HTTP_HOST'])?((!empty($_SERVER['HTTPS'])?'https':'http').'://'.$_SERVER['HTTP_HOST'].dirname($_SERVER['SCRIPT_NAME'])):'http://localhost/simantab').'/index.php?page=verify&code='.$code;
        $pdf=new TCPDF('P','mm','A4',true,'UTF-8',false);$pdf->SetCreator('SIMANTAP');$pdf->SetTitle($d['title']);$pdf->SetMargins(25,22,25);$pdf->AddPage();$pdf->SetFont('helvetica','B',14);$pdf->Cell(0,8,'UNIVERSITAS MUHAMMADIYAH PONOROGO',0,1,'C');$pdf->SetFont('helvetica','',9);$pdf->Cell(0,5,'Sistem Manajemen Surat dan Penugasan Terpadu',0,1,'C');$pdf->Ln(8);$pdf->SetFont('helvetica','B',13);$pdf->Cell(0,7,strtoupper($d['type_name']),0,1,'C');$pdf->SetFont('helvetica','',10);$pdf->Cell(0,6,$d['number']?:'DRAF',0,1,'C');$pdf->Ln(12);$pdf->SetFont('helvetica','',11);$pdf->writeHTML('<p>Dengan ini menerangkan dan menetapkan dokumen dengan perihal:</p><h3 style="text-align:center">'.htmlspecialchars($d['title']).'</h3><p>'.nl2br(htmlspecialchars($d['summary']?:'Dokumen diterbitkan melalui SIMANTAP dan berlaku sesuai ketentuan institusi.')).'</p>',true,false,true,false,'');$pdf->write2DBarcode($verifyUrl,'QRCODE,H','',230,32,32,[], 'N');$pdf->SetY(-55);$pdf->SetFont('helvetica','',9);$pdf->Cell(0,5,'Ditandatangani secara elektronik melalui SIMANTAP',0,1,'R');$pdf->Cell(0,5,date('d-m-Y H:i').' WIB',0,1,'R');$bytes=$pdf->Output('', 'S');$dir=dirname(__DIR__,2).'/storage/private/documents/'.$documentId;if(!is_dir($dir))mkdir($dir,0770,true);$path=$dir.'/final-'.bin2hex(random_bytes(8)).'.pdf';file_put_contents($path,$bytes,LOCK_EX);$hash=hash('sha256',$bytes);$u=AuthService::requireUser();
        return Database::transaction(function(PDO $db)use($d,$documentId,$path,$bytes,$hash,$code,$u){$q=$db->prepare("INSERT INTO document_files(document_id,uploaded_by,file_role,original_name,storage_path,mime_type,extension,file_size,checksum_sha256) VALUES(?,?,'final_pdf',? ,?,'application/pdf','pdf',?,?)");$q->execute([$documentId,$u['id'],($d['number']?:'dokumen').'.pdf',$path,strlen($bytes),$hash]);$fileId=(int)$db->lastInsertId();$db->prepare('UPDATE documents SET final_hash=?,verification_code=?,final_file_id=?,status="signed",signed_at=NOW() WHERE id=?')->execute([$hash,$code,$fileId,$documentId]);$db->prepare("INSERT INTO signatures(document_id,signer_user_id,signer_employee_id,signature_type,signed_hash,ip_address) VALUES(?,?,?,'internal_image',?,?)")->execute([$documentId,$u['id'],$d['signer_employee_id'],$hash,Security::clientIp()]);AuditService::log('document.signed','document',$documentId,null,['hash'=>$hash,'verification_code'=>$code]);return ['file_id'=>$fileId,'hash'=>$hash,'verification_code'=>$code];});
    }
}
